  [220106] = { "Nomina tuo vice un membro del gruppo, condividendo questa missione perché possa completarla insieme a te.\nPermette di condividere questa missione con i membri del gruppo.", 0x0ad93c3f, "u" },
  [220164] = { "Ti insegna una nuova abilità d'incisione.", 0xbc8956a2, "u" },
  [220165] = { "Ti insegna una nuova abilità d'incisione.", 0xbc8956a2, "u" },
  [220167] = { "Polvere tombale dal luogo di riposo di qualcuno assassinato da coloro che più amava...", 0x595f352f, "u" },
  [220168] = { "Un elisir di fuoco, creato con mani ferme e una mente instabile...", 0x297076f6, "u" },
  [220169] = { "Un simbolo di fede, donato da qualcuno che ha scoperto un nuovo scopo...", 0xebc05763, "u" },
  [220216] = { "Indebolisci Calefactus lo Scatenato.", 0xbcba3518, "u" },
  [220217] = { "Ti insegna una nuova abilità d'incisione.", 0xbc8956a2, "u" },
  [220345] = { "Descrive una varietà di potenti rituali di sangue. Un'aggiunta controversa alla collezione di qualsiasi biblioteca.", 0xd9cba5ad, "u" },
  [220346] = { "Coperto di note illeggibili e diagrammi scarabocchiati da una mano malferma. Potrebbe comunque essere un'aggiunta dignitosa alla collezione di qualsiasi biblioteca.", 0xe3ef334c, "u" },
  [220347] = { "Le parole nuotano sulla pagina, sfuggendo a ogni tentativo di leggerle. Un'aggiunta enigmatica alla collezione di qualsiasi biblioteca.", 0xfbfc8bcb, "u" },
  [220348] = { "Una guida al ruolo della magia elementare nella raffinata società degli ⟦Highborne=Alti Nobili⟧. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0x4cbbb1a5, "u" },
  [220349] = { "Solide tecniche architettoniche capaci di resistere a tutto, tranne che ai disastri più catastrofici. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0x0f4f4783, "u" },
  [220350] = { "Note sulle proprietà psicotrope di varie tossine e veleni. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0x9a63e401, "u" },
  [220351] = { "Permette allo Sciamano di vedere gli spiriti elementali.\nUn intruglio torbido. Una strana influenza di dubbia origine contamina una magia altrimenti riconoscibile.", 0x30414fb1, "u" },
  [220352] = { "Tecniche naniche per applicare la magia alla metallurgia, all'estrazione a cielo aperto e all'industria pesante. Un'aggiunta istruttiva, seppur cupa, alla collezione di qualsiasi biblioteca.", 0x5e1acf71, "u" },
  [220353] = { "Una raccolta d'anteguerra di incantesimi e teorie arcane ormai cadute quasi del tutto in disuso. Un'ottima aggiunta alla collezione di qualsiasi biblioteca.", 0xc9653d3e, "u" },
